// Title case for item and artifact names, keeping short joining words lowercase (e.g. Boots of Valor).
function titleCase(text) {
  return text.replace(/\S+/g, (word, index) => index && ['of', 'the', 'and'].includes(word) ? word : word[0].toUpperCase() + word.slice(1));
}

function buildVariants(item) {
  return Array.from({ length: 25 }, (_, index) => {
    const tier = 4 + Math.floor(index / 5);
    const enchantment = index % 5;
    const material = name => `T${tier}_${name}${enchantment ? `_LEVEL${enchantment}@${enchantment}` : ''}`;
    const stone = ENCHANT_STONES[enchantment];
    return {
      tier,
      enchantment,
      id: `T${tier}_${item.base}${enchantment ? `@${enchantment}` : ''}`,
      // Recipe entries: [name, id, count, options]. options === true marks an artifact; { ingredient: true } marks
      // a rare creature ingredient (shapeshifter staffs): never enchanted or returned, and odd tiers use 1 of the
      // same tier while even tiers use 2 from the tier below (T4: 2× T3, T5: 1× T5, T6: 2× T5…).
      materials: item.recipe.filter(([, , , options]) => options !== true).map(([name, id, count, options]) => options?.ingredient
        ? { name, id: `T${tier % 2 ? tier : tier - 1}_${id}`, count: tier % 2 ? 1 : 2, noReturn: true }
        : { name, id: material(id), count }),
      artifact: item.recipe.filter(([, , , options]) => options === true).map(([name, id, count]) => ({ name: titleCase(name), id: `T${tier}_${id}`, count }))[0] || null,
      enchant: stone ? { name: stone, id: `T${tier}_${stone.toUpperCase()}`, count: item.enchantCount } : null
    };
  });
}
